#include "ps2homebrew_catalogue.h"
#include <ctype.h>
#include <stdio.h>
#include <string.h>

const ps2hb_category_t ps2hb_categories[8] = {
 {"Exploits","/exploits/"},{"Loaders","/loaders/"},{"Apps","/apps/"},
 {"System Apps","/sys_apps/"},{"Emulators","/emulators/"},{"Games","/games/"},
 {"Diagnostics","/diag/"},{"UMCS","/umcs/"}
};

static int has_prefix_ci(const char *s,const char *p){while(*p){if(tolower((unsigned char)*s++)!=tolower((unsigned char)*p++))return 0;}return 1;}
static int safe_chars(const char *s){if(!s||!*s)return 0;for(;*s;s++){unsigned char c=(unsigned char)*s;if(c<=32||c==127||c=='\\'||c=='#')return 0;}return 1;}
static int parse_host_path(const char *url,const char *host,const char **path){
 if(!safe_chars(url)||!has_prefix_ci(url,"https://"))return 0;
 const char *p=url+8,*slash=strchr(p,'/'),*q=strchr(p,'?');const char *end=slash?slash:(q?q:url+strlen(url));
 if((q&&q<end)|| (size_t)(end-p)!=strlen(host)||strncasecmp(p,host,strlen(host)))return 0;
 if(path)*path=slash?slash:(q?q:url+strlen(url));
 return 1;
}
static int path_ok(const char *p){if(!p||*p!='/')return 0;const char *end=strpbrk(p,"?");size_t n=end?(size_t)(end-p):strlen(p);if(n==0||n>700)return 0;for(size_t i=0;i<n;i++)if(p[i]=='%')return 0;const char *s=p;while((s=strstr(s,".."))){if((s==p||s[-1]=='/')&&(s[2]=='/'||s[2]==0||s[2]=='?'))return 0;s+=2;}return 1;}
static int path_category(const char *p,int cat){if(cat<0||cat>=8||!path_ok(p))return 0;size_t n=strlen(ps2hb_categories[cat].path);if(strncmp(p,ps2hb_categories[cat].path,n))return 0;return 1;}
int ps2hb_valid_category_url(const char *url,int category){const char *p=NULL;if(category<0||category>=8||!parse_host_path(url,"ps2homebrewstore.com",&p)||!path_ok(p))return 0;const char *q=strchr(p,'?');size_t n=q?(size_t)(q-p):strlen(p);return n==strlen(ps2hb_categories[category].path)&&!strncmp(p,ps2hb_categories[category].path,n);}
int ps2hb_valid_entry_url(const char *url){const char *p=NULL;if(!parse_host_path(url,"ps2homebrewstore.com",&p)||!path_ok(p))return 0;for(int i=0;i<8;i++){size_t n=strlen(ps2hb_categories[i].path);if(!strncmp(p,ps2hb_categories[i].path,n)){const char *tail=p+n;while(*tail=='/')tail++;if(!*tail||*tail=='?')return 1;return 1;}}return 0;}
int ps2hb_asset_kind_from_url(const char *url){const char *p=NULL;if(!parse_host_path(url,"downloads.ps2homebrewstore.com",&p)||!path_ok(p))return 0;const char *end=strpbrk(p,"?#");size_t n=end?(size_t)(end-p):strlen(p);const char *slash=p+n;while(slash>p&&slash[-1]!='/')slash--;size_t l=(size_t)(p+n-slash);if(l>=4&&has_prefix_ci(slash+l-4,".psu"))return PS2HB_ASSET_PSU;if(l>=4&&has_prefix_ci(slash+l-4,".zip"))return PS2HB_ASSET_ZIP;return 0;}
int ps2hb_requires_verified_tls(const char *url){if(ps2hb_asset_kind_from_url(url))return 1;const char *p=NULL;if(!parse_host_path(url,"ps2homebrewstore.com",&p))return 0;for(int i=0;i<8;i++)if(path_category(p,i))return 1;return ps2hb_valid_entry_url(url);}
int ps2hb_redirect_allowed(const char *url){return ps2hb_asset_kind_from_url(url)!=0;}
static void decode_entities(const char *src,size_t len,char *out,size_t cap){size_t n=0;for(size_t i=0;i<len&&n+1<cap;){if(src[i]=='&'){struct {const char *a;char c;} e[]={{"&amp;",'&'},{"&quot;",'"'},{"&#39;",'\''},{"&apos;",'\''},{"&lt;",'<'},{"&gt;",'>'}};int found=0;for(unsigned k=0;k<sizeof(e)/sizeof(e[0]);k++){size_t z=strlen(e[k].a);if(i+z<=len&&!strncasecmp(src+i,e[k].a,z)){out[n++]=e[k].c;i+=z;found=1;break;}}if(found)continue;}unsigned char c=(unsigned char)src[i++];if(c=='<'){while(i<len&&src[i]!='>')i++;if(i<len)i++;if(n&&out[n-1]!=' ')out[n++]=' ';continue;}if(isspace(c)){if(n&&out[n-1]!=' ')out[n++]=' ';continue;}if(c>=32&&c!=127)out[n++]=(char)c;}while(n&&out[n-1]==' ')n--;out[n]=0;}
static int get_attr(const char *a,const char *end,const char *key,char *out,size_t cap){size_t k=strlen(key);while(a<end){while(a<end&&(isspace((unsigned char)*a)||*a=='/'))a++;const char *s=a;while(a<end&&(isalnum((unsigned char)*a)||*a=='-'||*a==':'))a++;if(a==s){a++;continue;}size_t n=(size_t)(a-s);while(a<end&&isspace((unsigned char)*a))a++;if(n==k&&!strncasecmp(s,key,k)&&a<end&&*a=='='){a++;while(a<end&&isspace((unsigned char)*a))a++;char quote=0;if(a<end&&(*a=='\''||*a=='\"'))quote=*a++;const char *v=a;if(quote){while(a<end&&*a!=quote)a++;if(a>=end)return 0;}else while(a<end&&!isspace((unsigned char)*a)&&*a!='>')a++;size_t z=(size_t)(a-v);if(z>=cap)z=cap-1;memcpy(out,v,z);out[z]=0;return 1;}if(a<end&&*a=='='){a++;if(a<end&&(*a=='\''||*a=='\"')){char q=*a++;while(a<end&&*a!=q)a++;if(a<end)a++;}else while(a<end&&!isspace((unsigned char)*a)&&*a!='>')a++;}}return 0;}
static int add_unique_entry(ps2hb_entry_t *o,int n,int cap,int cat,const char *title,const char *url){if(!title||!*title||!ps2hb_valid_entry_url(url))return n;for(int i=0;i<n;i++)if(!strcmp(o[i].detail_url,url))return n;if(n>=cap)return n;memset(&o[n],0,sizeof(o[n]));o[n].category=cat;snprintf(o[n].title,sizeof(o[n].title),"%s",title);snprintf(o[n].detail_url,sizeof(o[n].detail_url),"%s",url);return n+1;}
static int resolve_entry_href(const char *href,int cat,char *url,size_t cap){if(!href||!*href||strchr(href,'#'))return 0;if(has_prefix_ci(href,"https://")){snprintf(url,cap,"%s",href);return ps2hb_valid_entry_url(url)&&!strncmp(url+strlen("https://ps2homebrewstore.com"),ps2hb_categories[cat].path,strlen(ps2hb_categories[cat].path));}if(href[0]!='/')return 0;snprintf(url,cap,"https://ps2homebrewstore.com%s",href);return ps2hb_valid_entry_url(url)&&!strncmp(url+strlen("https://ps2homebrewstore.com"),ps2hb_categories[cat].path,strlen(ps2hb_categories[cat].path));}
static const char *find_ci(const char *p,const char *needle){size_t n=strlen(needle);for(;p&&*p;p++)if(!strncasecmp(p,needle,n))return p;return NULL;}
static const char *find_open_tag(const char *p,const char *name){char token[16];snprintf(token,sizeof(token),"<%s",name);while((p=find_ci(p,token))){char c=p[strlen(token)];if(c=='>'||c=='/'||isspace((unsigned char)c))return p;p++;}return NULL;}
static void block_title(const char *begin,const char *end,char *title,size_t cap){const char *tag=NULL,*open_end=NULL,*close=NULL;const char *tags[]={"<h2","<h3","<h4","<p"};for(unsigned i=0;i<4&&!tag;i++){tag=find_ci(begin,tags[i]);if(tag&&tag<end){open_end=strchr(tag,'>');if(!open_end||open_end>=end){tag=NULL;continue;}close=find_ci(open_end+1,i<3?(i==0?"</h2>":(i==1?"</h3>":"</h4>")):"</p>");if(!close||close>=end)tag=NULL;}else tag=NULL;}if(tag)decode_entities(open_end+1,(size_t)(close-(open_end+1)),title,cap);else title[0]=0;}
static int add_card_entry(ps2hb_entry_t *out,int n,int cap,int category,const char *title){if(!title||!*title)return n;char section[128];snprintf(section,sizeof(section),"https://ps2homebrewstore.com%s",ps2hb_categories[category].path);for(int i=0;i<n;i++)if(!strcmp(out[i].title,title))return n;if(n>=cap)return n;memset(&out[n],0,sizeof(out[n]));out[n].category=category;snprintf(out[n].title,sizeof(out[n].title),"%s",title);snprintf(out[n].detail_url,sizeof(out[n].detail_url),"%s",section);return n+1;}
int ps2hb_parse_category(const char *html,int category,ps2hb_entry_t *out,int cap){if(!html||!out||cap<=0||category<0||category>=8||strnlen(html,2*1024*1024)>=2*1024*1024)return 0;int n=0;const char *p=html;while((p=find_open_tag(p,"li"))){const char *gt=strchr(p,'>');if(!gt)break;const char *end=find_ci(gt+1,"</li>");if(!end){p=gt+1;continue;}char title[128]={0};block_title(gt+1,end,title,sizeof(title));int supported=0;const char *a=gt+1;while((a=find_open_tag(a,"a"))&&a<end){const char *ag=strchr(a,'>');if(!ag||ag>=end)break;char href[PS2HB_URL_SIZE]={0};if(get_attr(a+2,ag,"href",href,sizeof(href))&&ps2hb_asset_kind_from_url(href))supported=1;a=ag+1;}if(supported)n=add_card_entry(out,n,cap,category,title);p=end+5;}
 /* Compatibility with pages that expose item-detail anchors instead of cards. */
 if(n==0){p=html;while((p=strchr(p,'<'))){if(!has_prefix_ci(p,"<a")||!(isspace((unsigned char)p[2])||p[2]=='>'||p[2]=='/')){p++;continue;}const char *gt=strchr(p,'>');if(!gt)break;const char *end=find_ci(gt+1,"</a");if(!end){p=gt+1;continue;}char href[384]={0},full[384]={0},title[128]={0};if(get_attr(p+2,gt,"href",href,sizeof(href))&&resolve_entry_href(href,category,full,sizeof(full))){decode_entities(gt+1,(size_t)(end-(gt+1)),title,sizeof(title));n=add_unique_entry(out,n,cap,category,title,full);}p=end+3;}}
 return n;}

static int add_asset(ps2hb_asset_t *o,int n,int cap,int kind,const char *title,const char *label,const char *url){if(n>=cap)return n;for(int i=0;i<n;i++)if(!strcmp(o[i].url,url))return n;memset(&o[n],0,sizeof(o[n]));o[n].kind=kind;snprintf(o[n].title,sizeof(o[n].title),"%s",title?title:"");snprintf(o[n].label,sizeof(o[n].label),"%s",(label&&*label)?label:(kind==PS2HB_ASSET_PSU?"PSU file":"ZIP archive"));snprintf(o[n].url,sizeof(o[n].url),"%s",url);return n+1;}
static int parse_assets_range(const char *begin,const char *end,const char *title,ps2hb_asset_t *out,int cap){int n=0;const char *p=begin;while((p=find_open_tag(p,"a"))&&p<end){const char *gt=strchr(p,'>');if(!gt||gt>=end)break;const char *close=find_ci(gt+1,"</a");if(!close||close>end)break;char href[PS2HB_URL_SIZE]={0},label[96]={0};if(get_attr(p+2,gt,"href",href,sizeof(href))){int kind=ps2hb_asset_kind_from_url(href);if(kind){decode_entities(gt+1,(size_t)(close-(gt+1)),label,sizeof(label));n=add_asset(out,n,cap,kind,title,label,href);}}p=close+3;}return n;}
int ps2hb_parse_entry(const char *html,const char *title,ps2hb_asset_t *out,int cap){if(!html||!out||cap<=0||strnlen(html,2*1024*1024)>=2*1024*1024)return 0;const char *p=html;int found_card=0,n=0;while((p=find_open_tag(p,"li"))){const char *gt=strchr(p,'>');if(!gt)break;const char *end=find_ci(gt+1,"</li>");if(!end){p=gt+1;continue;}char card_title[128]={0};block_title(gt+1,end,card_title,sizeof(card_title));if(title&&*title&&card_title[0]&&!strcasecmp(card_title,title)){found_card=1;n=parse_assets_range(gt+1,end,title,out,cap);break;}p=end+5;}if(found_card)return n;return parse_assets_range(html,html+strlen(html),title,out,cap);}
int ps2hb_validate_zip_file(const char *path){if(!path)return -1;FILE *f=fopen(path,"rb");if(!f)return -1;unsigned char sig[4];size_t n=fread(sig,1,sizeof(sig),f);fclose(f);if(n<4||sig[0]!='P'||sig[1]!='K')return -1;if((sig[2]==3&&sig[3]==4)||(sig[2]==5&&sig[3]==6)||(sig[2]==7&&sig[3]==8))return 0;return -1;}
